        report.setHeaders(getHeaders());
        report.setRows(getRows(param));
        report.setTotals(getTotals(param));
        return report;
    }

    private List<String> getHeaders() {
        List<String> headers = new ArrayList<>();
        headers.add("Facility Name");
        headers.add("Region");
        headers.add("District");
        headers.add("Total Reporting Rate");
        headers.add("Non-Reporting Rate");
        return headers;
    }

    private List<List<String>> getRows(NonReportingFacilityParam param) {
        List<List<String>> rows = new ArrayList<>();
        List<ResultRow> resultRows = mapper.getNonReportingFacilities(param, new RowBounds(0, Integer.MAX_VALUE));
        for (ResultRow row : resultRows) {
            List<String> rowData = new ArrayList<>();
            rowData.add(row.getFacilityName());
            rowData.add(row.getRegion());
            rowData.add(row.getDistrict());
            rowData.add(row.getTotalReportingRate());
            rowData.add(row.getNonReportingRate());
            rows.add(rowData);
        }

