    public MasterReport getReport(NonReportingFacilityParam param) {
        MasterReport report = new MasterReport();
        report.setHeaders(getHeaders());
        report.setRows(new ArrayList<>());

        Map<String, Object> parameters = ParameterAdaptor.adapt(param);
        List<NameCount> nonReportingFacilities = nonReportingFacilityReportMapper.getNonReportingFacilities(parameters);
        List<NameCount> allFacilities = nonReportingFacilityReportMapper.getAllFacilities(parameters);

        int totalNonReporting = nonReportingFacilities.stream().mapToInt(NameCount::getCount).sum();
        int totalFacilities = allFacilities.stream().mapToInt(NameCount::getCount).sum();

        report.setTotalNonReporting(totalNonReporting);
        report.setTotalFacilities(totalFacilities);

        if (totalFacilities > 0) {
            double percentageNonReporting = (double) totalNonReporting / totalFacilities * 100;
            report.setPercentageNonReporting(percentageNonReporting);
        } else {
            report.setPercentageNonReporting(0.0);
        }

