	/* Private helpers */

	private static RuntimeException ass(Object... msg)
	{
		if((msg == null) || (msg.length == 0))
			return new AssertionError();

		StringBuilder sb = new StringBuilder();
		for(Object m : msg)
			sb.append(m).append(' ');

