public RuleEngineConfig buildRuleEngineConfig(OMElement ruleConfigElement) throws RuleConfigurationException {
        RuleEngineConfig ruleEngineConfig = new RuleEngineConfig();
        try {
            Iterator<OMElement> providerElements = ruleConfigElement.getChildElements();
            while (providerElements.hasNext()) {
                OMElement providerElement = providerElements.next();
                if (providerElement.getLocalName().equals(Constants.PROVIDER_ELEMENT)) {
                    RuleEngineProvider provider = new RuleEngineProvider();
                    provider.setName(providerElement.getAttributeValue(new QName(Constants.NAME_ATTRIBUTE)));
                    provider.setClassName(providerElement.getAttributeValue(new QName(Constants.CLASS_NAME_ATTRIBUTE)));
                    provider.setPriority(Integer.parseInt(providerElement.getAttributeValue(new QName(Constants.PRIORITY_ATTRIBUTE))));
                    provider.setConfigLocation(providerElement.getAttributeValue(new QName(Constants.CONFIG_LOCATION_ATTRIBUTE)));
                    ruleEngineConfig.addProvider(provider);
                }
            }
        } catch (Exception e) {
            throw new RuleConfigurationException("Error while building rule engine configuration", e);
        }
        return ruleEngineConfig;
    }
}

