package gov.samhsa.consents2share.c32;

import java.io.InputStream;
import java.net.URI;
import java.net.URISyntaxException;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

import org.springframework.stereotype.Component;

@Component
public class UriResolverImpl implements UriResolver {

    private final Map<String, InputStream> cache = new ConcurrentHashMap<>();

    @Override
    public InputStream resolve(URI uri) {
        if (uri == null) {
            return null;
        }

        try {
            String uriString = uri.toString();
            if (cache.containsKey(uriString)) {
                return cache.get(uriString);
            }

            InputStream inputStream = getClass().getClassLoader().getResourceAsStream(uriString);
            if (inputStream != null) {
                cache.put(uriString, inputStream);
            }
            return inputStream;
        } catch (Exception e) {
            return null;
        }
    }
}

